// --- Asset Generator ---
const generateSvgAsset = (primaryColor: string, secondaryColor: string, style: 'gradient' | 'geometric' | 'organic') => {
  const width = 800;
  const height = 1000;
  let content = '';

  if (style === 'gradient') {
    // Elegant soft gradient with subtle circle overlay
    content = `
      <defs>
        <linearGradient id="grad" x1="0%" y1="0%" x2="0%" y2="100%">
          <stop offset="0%" style="stop-color:${secondaryColor};stop-opacity:1" />
          <stop offset="100%" style="stop-color:${primaryColor};stop-opacity:0.1" />
        </linearGradient>
      </defs>
      <rect width="${width}" height="${height}" fill="url(#grad)" />
      <circle cx="${width}" cy="0" r="${width * 0.6}" fill="${primaryColor}" fill-opacity="0.05" />
      <circle cx="0" cy="${height}" r="${width * 0.8}" fill="${primaryColor}" fill-opacity="0.05" />
    `;
  } else if (style === 'geometric') {
    // Modern grid and frame
    content = `
      <rect width="${width}" height="${height}" fill="${secondaryColor}" />
      <defs>
        <pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse">
          <path d="M 40 0 L 0 0 0 40" fill="none" stroke="${primaryColor}" stroke-width="1" opacity="0.08"/>
        </pattern>
      </defs>
      <rect width="${width}" height="${height}" fill="url(#grid)" />
      <rect x="40" y="40" width="${width - 80}" height="${height - 80}" fill="none" stroke="${primaryColor}" stroke-width="2" opacity="0.3" />
      <rect x="60" y="60" width="${width - 120}" height="${height - 120}" fill="none" stroke="${primaryColor}" stroke-width="1" opacity="0.2" />
    `;
  } else {
    // Organic waves (Festive)
    content = `
      <rect width="${width}" height="${height}" fill="${secondaryColor}" />
      <path d="M0,0 C${width * 0.5},150 ${width * 0.5},150 ${width},0 L${width},0 L0,0 Z" fill="${primaryColor}" fill-opacity="0.1" />
      <path d="M0,${height} C${width * 0.5},${height - 200} ${width * 0.5},${height - 200} ${width},${height} L${width},${height} L0,${height} Z" fill="${primaryColor}" fill-opacity="0.15" />
      <circle cx="${width / 2}" cy="${height / 2}" r="${width * 0.35}" fill="none" stroke="${primaryColor}" stroke-width="2" opacity="0.1" />
    `;
  }

  const svg = `
    <svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">
      ${content}
    </svg>
  `;

  return `data:image/svg+xml;base64,${btoa(svg)}`;
};

// Helper to generate template object
const createAssetTemplate = (id: string, name: string, colorPair: [string, string], style: 'gradient' | 'geometric' | 'organic') => {
  const assetUrl = generateSvgAsset(colorPair[0], colorPair[1], style);
  return {
    id,
    imageUrl: assetUrl,
    thumbnailUrl: assetUrl,
    alt: name,
  };
};

